@push('scripts')<script>function downloadProfileCard(){const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');canvas.width=1200;canvas.height=700;ctx.fillStyle='#030304';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#fff';ctx.lineWidth=4;ctx.strokeRect(20,20,1160,660);ctx.fillStyle='#fff';ctx.font='bold 48px Oswald';ctx.fillText('GINHAWA ORDER',70,100);ctx.font='24px Courier Prime';ctx.fillStyle='#c0c0c0';ctx.fillText('GINHAWA GLOBAL COVENANT',70,140);ctx.fillStyle='#fff';ctx.font='bold 42px Oswald';ctx.fillText(document.getElementById('profileCardName').textContent,70,280);ctx.font='24px Courier Prime';ctx.fillStyle='#c0c0c0';ctx.fillText('TITLE / ROLE: '+document.getElementById('profileCardRole').textContent,70,340);ctx.fillText('JURISDICTION: '+document.getElementById('profileCardRegion').textContent,70,390);ctx.fillStyle='#fff';ctx.fillText('SERIAL: '+document.getElementById('profileCardSerial').textContent,70,560);const link=document.createElement('a');link.download='GINHAWA_CITIZEN_ID.png';link.href=canvas.toDataURL('image/png');link.click()}</script>@endpush
